using Gimnasio.Domain.Entities;namespace Gimnasio.Tests.Domain;public sealed class PlanningTests{[Fact]public void GoalUpdateCreatesNewVersion(){var x=new PersonalGoal(Guid.NewGuid(),"Carrera");x.Configure("Carrera","Rendimiento",10,8,"min",new(2026,8,1),new(2026,12,1),"active",null,false);x.Configure("Carrera","Rendimiento",10,7.5m,"min",new(2026,8,1),new(2026,12,1),"active",null,true);Assert.Equal(2,x.Version);}[Fact]public void CycleRejectsInvalidDates(){var x=new TrainingCycle(Guid.NewGuid(),"Base");Assert.Throws<ArgumentException>(()=>x.Configure("Base",new(2026,9,1),new(2026,8,1),"Fuerza",3,"planned",null,false));}}
